from solution import is_simple_power
import pytest
from hypothesis import given, strategies as st


def _ref(x, n):
    # Obviously-correct reference for integer inputs.
    # Exists integer k with n**k == x (Python semantics, n**0 == 1 including 0**0).
    if x == 1:
        return True
    if n == 0:
        return x == 0
    if n == 1:
        return False  # x != 1 here, 1**k is always 1
    if n == -1:
        return x == -1  # x != 1 here, (-1)**k is 1 or -1
    if x == 0:
        return False  # n != 0 here, n**k never 0
    p = n
    for _ in range(100):
        if p == x:
            return True
        if abs(p) > abs(x):
            break
        # avoid huge ints
        if abs(p) > 10**18:
            break
        p = p * n
    return False


# ---- explicit spec examples ----
def test_example_1_is_power():
    assert is_simple_power(1, 4) is True


def test_example_2_is_power():
    assert is_simple_power(2, 2) is True


def test_example_8_is_power_of_2():
    assert is_simple_power(8, 2) is True


def test_example_3_not_power_of_2():
    assert is_simple_power(3, 2) is False


def test_example_3_not_power_of_1():
    assert is_simple_power(3, 1) is False


def test_example_5_not_power_of_3():
    assert is_simple_power(5, 3) is False


# ---- properties ----

def test_one_is_simple_power_of_any_nonzero_n():
    for n in [-10, -2, -1, 1, 2, 3, 4, 10, 100]:
        assert is_simple_power(1, n) is True


def test_n_equals_1_only_one_is_power():
    # 1**k == 1 for all k, never anything else
    for x in [-5, -1, 0, 2, 3, 5, 8, 100]:
        assert is_simple_power(x, 1) is False


def test_n_equals_1_with_one_is_true():
    assert is_simple_power(1, 1) is True


def test_zero_base_cases():
    assert is_simple_power(0, 0) is True  # 0**0 == 1? no: x==1 rule aside; 0**1==0 so 0 is power of 0
    # Actually check: x=0 is 0**1
    assert is_simple_power(0, 2) is False
    assert is_simple_power(0, -2) is False
    assert is_simple_power(2, 0) is False
    assert is_simple_power(3, 0) is False
    assert is_simple_power(0, 1) is False


def test_minus_one_base():
    assert is_simple_power(1, -1) is True
    assert is_simple_power(-1, -1) is True
    assert is_simple_power(0, -1) is False
    assert is_simple_power(2, -1) is False
    assert is_simple_power(-2, -1) is False


@given(n=st.integers(min_value=2, max_value=10), k=st.integers(min_value=0, max_value=6))
def test_constructed_positive_powers_are_true(n, k):
    x = n ** k
    assert is_simple_power(x, n) is True


@given(n=st.integers(min_value=-10, max_value=-2), k=st.integers(min_value=0, max_value=6))
def test_constructed_negative_base_powers_are_true(n, k):
    x = n ** k
    assert is_simple_power(x, n) is True


@given(
    x=st.integers(min_value=-200, max_value=200),
    n=st.integers(min_value=-5, max_value=5),
)
def test_reference_equivalence_small_ints(x, n):
    assert is_simple_power(x, n) is _ref(x, n)


@given(
    x=st.integers(min_value=-1000, max_value=1000),
    n=st.integers(min_value=2, max_value=10),
)
def test_reference_equivalence_positive_base(x, n):
    assert is_simple_power(x, n) is _ref(x, n)


def test_known_powers_true():
    assert is_simple_power(16, 2) is True
    assert is_simple_power(27, 3) is True
    assert is_simple_power(64, 4) is True
    assert is_simple_power(64, 2) is True
    assert is_simple_power(-8, -2) is True
    assert is_simple_power(9, 3) is True
    assert is_simple_power(4, 2) is True


def test_known_non_powers_false():
    assert is_simple_power(12, 2) is False
    assert is_simple_power(10, 3) is False
    assert is_simple_power(7, 2) is False
    assert is_simple_power(-8, 2) is False
    assert is_simple_power(8, -2) is False
    assert is_simple_power(2, 3) is False
    assert is_simple_power(6, 6) is False or True  # placeholder replaced below
    # real check:
    assert is_simple_power(6, 3) is False
    assert is_simple_power(100, 10) is False
    assert is_simple_power(100, 3) is False
